mapper.select:
select d.id from devices d join user_device_selections u on u.device_id = d.id
where d.serial_number = #{serialNumber} and u.user_id = #{userId}
limit 1

mapper.update:
update sensor_binding_challenges set confirmed_at = #{confirmedAt}
where token_hash = #{tokenHash} and sensor_id = #{sensorId}
  and expires_at > #{validAfter} and used_at is null

update sensor_workout_sessions
set status = 'COMPLETED', training_state = 'idle', ended_at = last_motion_at, end_reason = 'IDLE'
where schema_version = #{schemaVersion} and status = 'ACTIVE' and last_motion_at <= #{cutoff}
and sensor_id = #{sensorId}

update sensor_workout_sessions
set status = 'COMPLETED', training_state = 'idle', ended_at = last_motion_at, end_reason = #{reason}
where id = #{sessionId} and status = 'ACTIVE'

update sensor_workout_sessions
set status = 'COMPLETED', training_state = 'idle', ended_at = last_motion_at, end_reason = #{reason}
where sensor_id = #{sensorId} and status = 'ACTIVE'
